import type { AnalysisSnapshot } from "@/lib/domain/analysis";

const sentences = new Intl.Segmenter("ko", { granularity: "sentence" });
const MAX_LENGTH = 160;

// Every excerpt is a contiguous slice of the supplied record, never generated by the model.
export function recordExcerpts(recordText: string) {
  const excerpts: string[] = [];
  for (const { segment } of sentences.segment(recordText)) {
    let rest = segment.trim();
    while (rest.length > MAX_LENGTH) {
      const prefix = rest.slice(0, MAX_LENGTH);
      const naturalBreak = prefix.lastIndexOf(" ");
      const end = naturalBreak > MAX_LENGTH / 2 ? naturalBreak + 1 : MAX_LENGTH;
      excerpts.push(rest.slice(0, end).trim());
      rest = rest.slice(end).trim();
    }
    if (rest) excerpts.push(rest);
  }
  return excerpts;
}

export function indexedSubjects(snapshot: AnalysisSnapshot) {
  let excerptId = 0;
  return snapshot.subjects.map(({ records, ...subject }) => ({
    ...subject,
    records: records.map(({ id, recordText, memo }) => ({
      id,
      memo,
      excerpts: recordExcerpts(recordText).map((text) => ({ id: ++excerptId, text })),
    })),
  }));
}
